using System;using System.IO;using System.Linq;using System.Collections.Generic;using Mono.Cecil;using Mono.Cecil.Cil;
public static class DecodeConstants {
 static IEnumerable<TypeDefinition> Types(IEnumerable<TypeDefinition> ts){foreach(var t in ts){yield return t;foreach(var n in Types(t.NestedTypes))yield return n;}}
 public static void Main(string[] args){using(var m=ModuleDefinition.ReadModule(args[0])){var global=m.Types[0];var entries=new List<Tuple<MethodReference,int>>();foreach(var t in Types(m.Types))foreach(var f in t.Methods.Where(x=>x.HasBody))foreach(var i in f.Body.Instructions){var g=i.Operand as GenericInstanceMethod;if(g==null||g.DeclaringType.FullName!=global.FullName||g.GenericArguments.Count!=1||g.GenericArguments[0].FullName!="System.String"||i.Previous==null)continue;int k;var p=i.Previous;while(p!=null&&(p.OpCode==OpCodes.Nop||((p.OpCode==OpCodes.Br_S||p.OpCode==OpCodes.Br)&&p.Operand==i)))p=p.Previous;if(p==null)continue;if(p.OpCode==OpCodes.Ldc_I4)k=(int)p.Operand;else if(p.OpCode==OpCodes.Ldc_I4_S)k=(sbyte)p.Operand;else continue;if(!entries.Any(e=>e.Item1.FullName==g.FullName&&e.Item2==k))entries.Add(Tuple.Create((MethodReference)g,k));}
 var probe=new TypeDefinition("ShenPulse.Tools","ConstantProbe",TypeAttributes.Public|TypeAttributes.Abstract|TypeAttributes.Sealed,m.TypeSystem.Object);m.Types.Add(probe);var decode=new MethodDefinition("Decode",MethodAttributes.Public|MethodAttributes.Static,new ArrayType(m.TypeSystem.String));probe.Methods.Add(decode);var il=decode.Body.GetILProcessor();il.Emit(OpCodes.Ldc_I4,entries.Count);il.Emit(OpCodes.Newarr,m.TypeSystem.String);for(int i=0;i<entries.Count;i++){il.Emit(OpCodes.Dup);il.Emit(OpCodes.Ldc_I4,i);il.Emit(OpCodes.Ldc_I4,entries[i].Item2);il.Emit(OpCodes.Call,entries[i].Item1);il.Emit(OpCodes.Stelem_Ref);}il.Emit(OpCodes.Ret);File.WriteAllLines(args[2],entries.Select(e=>e.Item1.ElementMethodToken()+":"+e.Item2));
 foreach(var t in m.Types.ToArray())if(t!=global&&t!=probe)m.Types.Remove(t);m.Assembly.CustomAttributes.Clear();m.CustomAttributes.Clear();m.Assembly.Name.Name="ShenPulse.ConstantProbe";m.Name="ShenPulse.ConstantProbe.dll";m.Write(args[1]);Console.WriteLine(entries.Count+" constants prepared");}}
 static uint ElementMethodToken(this MethodReference r){return ((GenericInstanceMethod)r).ElementMethod.MetadataToken.ToUInt32();}
}